import React from "react";
import styles from "./MovieList.module.css";
import MovieListItem from "./MovieListItem";

function MovieList({
  movie,
  IMAGE_BASE_URL,
  setCurMovie,
  setIsSelected,
  isSelected,
}) {
  return (
    <div className={styles.movieList}>
      <div className={styles.original}>
        <ul>
          {movie?.originals?.results?.map((original) => {
            return (
              <li
                key={original.id}
                onClick={() => {
                  setCurMovie(original);
                  if (original?.id === setCurMovie.id) {
                    setIsSelected(!isSelected);
                  }
                }}
              >
                <img
                  src={`${IMAGE_BASE_URL}${original["poster_path"]}`}
                  alt=""
                />
              </li>
            );
          })}
        </ul>
      </div>
      <MovieListItem
        movies={movie.trending}
        title={"Xu hướng"}
        IMAGE_BASE_URL={IMAGE_BASE_URL}
      ></MovieListItem>
      <MovieListItem
        movies={movie.topRated}
        title={"xếp hạng cao"}
        IMAGE_BASE_URL={IMAGE_BASE_URL}
      ></MovieListItem>
      <MovieListItem
        movies={movie.action}
        title={"Hành động"}
        IMAGE_BASE_URL={IMAGE_BASE_URL}
      ></MovieListItem>
      <MovieListItem
        movies={movie.comedy}
        title={"Hài"}
        IMAGE_BASE_URL={IMAGE_BASE_URL}
      ></MovieListItem>
      <MovieListItem
        movies={movie.horror}
        title={"Kinh dị"}
        IMAGE_BASE_URL={IMAGE_BASE_URL}
      ></MovieListItem>
      <MovieListItem
        movies={movie.romance}
        title={"Lãng mạn"}
        IMAGE_BASE_URL={IMAGE_BASE_URL}
      ></MovieListItem>
      <MovieListItem
        movies={movie.documentaries}
        title={"Tài liệu"}
        IMAGE_BASE_URL={IMAGE_BASE_URL}
      ></MovieListItem>
    </div>
  );
}

export default MovieList;
